package com.example.greetingcard; import android.os.Bundle; import android.view.View; import android.widget.ImageView; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { TextView tvGreetingTitle; ImageView ivBirthdayCard; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);tvGreetingTitle=findViewById(R.id.tvGreetingTitle);ivBirthdayCard=findViewById(R.id.ivBirthdayCard);} public void showGreetingCard(View v){tvGreetingTitle.setText("Happy Birthday");ivBirthdayCard.setVisibility(View.VISIBLE);}}
